% stats.m
function [m, s] = stats(x)
%STATS Mean and sample standard deviation of a vector.
    m = mean(x);
    s = std(x);
end

person.name = 'Ana';
person.age = 30;
fprintf('%s is %d\n', person.name, person.age)   % Ana is 30

c = {'Ana', 30, [1 2 3]};   % cell array with mixed types
c{2}                         % 30 (curly braces get the content)
class(c(2))                  % 'cell' (parentheses get a sub-cell)
names = {'Ana', 'Ben', 'Cleo'};
numel(names)                 % 3
upper(names{1})              % 'ANA'

% safe_sqrt.m
function r = safe_sqrt(x)
    if x < 0
        error('demo:negative', 'Input must be non-negative, got %g', x);
    end
    r = sqrt(x);
end
